package com.supportsphere.dao; import com.supportsphere.util.*; import java.sql.*; import java.util.*; public class AdminDAO { public Map<String,Integer> stats()throws Exception{Map<String,Integer>m=new LinkedHashMap<>();try(Connection c=DBConnection.getConnection()){for(String[]x:new String[][]{{"Total Users","SELECT COUNT(*) FROM users"},{"Active Volunteers","SELECT COUNT(*) FROM users WHERE role='VOLUNTEER' AND status='ACTIVE'"},{"Open Requests","SELECT COUNT(*) FROM assistance_requests WHERE status='OPEN'"},{"Active Assignments","SELECT COUNT(*) FROM assignments WHERE status IN('ASSIGNED','IN_PROGRESS')"},{"Completed Tasks","SELECT COUNT(*) FROM assistance_requests WHERE status='COMPLETED'"}}){try(Statement s=c.createStatement();ResultSet r=s.executeQuery(x[1])){r.next();m.put(x[0],r.getInt(1));}}}return m;} public List<Map<String,Object>> assignments()throws Exception{return list("SELECT a.assignment_id,a.request_id,v.name volunteer,ar.task_type,ar.status request_status,a.status assignment_status,a.assigned_at FROM assignments a JOIN users v ON v.user_id=a.volunteer_id JOIN assistance_requests ar ON ar.request_id=a.request_id ORDER BY a.assigned_at DESC");} public List<Map<String,Object>> feedback()throws Exception{return list("SELECT f.request_id,v.name volunteer,f.rating,f.comment,f.created_at FROM feedback f JOIN users v ON v.user_id=f.volunteer_id ORDER BY f.created_at DESC");} private List<Map<String,Object>> list(String q)throws Exception{List<Map<String,Object>>x=new ArrayList<>();try(Connection c=DBConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(q)){ResultSetMetaData md=r.getMetaData();while(r.next()){Map<String,Object>m=new LinkedHashMap<>();for(int i=1;i<=md.getColumnCount();i++)m.put(md.getColumnLabel(i),r.getObject(i));x.add(m);}}return x;} }
